import { useState } from "react";

const ADMIN_EMAIL = "";  // <-- replace with your real email
const ADMIN_PHONE = "+254 700 000000";            // <-- replace with your real phone number

export default function Contact() {
  const [form, setForm] = useState({ name: "", email: "", message: "" });
  const [sent, setSent] = useState(false);

  function handleChange(e) {
    setForm({ ...form, [e.target.name]: e.target.value });
  }

  function handleSubmit(e) {
    e.preventDefault();
    const subject = encodeURIComponent(`Message from ${form.name}`);
    const body = encodeURIComponent(`${form.message}\n\n— ${form.name} (${form.email})`);
    window.location.href = `mailto:${ADMIN_EMAIL}?subject=${subject}&body=${body}`;
    setSent(true);
  }

  return (
    <section className="page page--centered" style={{ flexDirection: "column", gap: "24px" }}>
      <div className="auth-form" style={{ textAlign: "center" }}>
        <h1>Contact us</h1>
        <p style={{ color: "var(--text-dim)", fontSize: "0.85rem" }}>Reach us directly, or send a message below.</p>
        <p style={{ margin: "12px 0 4px" }}>
          <a href={`mailto:${ADMIN_EMAIL}`} style={{ color: "var(--lime)", fontWeight: 600 }}>
            {ADMIN_EMAIL}
          </a>
        </p>
        <p style={{ margin: 0 }}>
          <a href={`tel:${ADMIN_PHONE.replace(/\s/g, "")}`} style={{ color: "var(--lime)", fontWeight: 600 }}>
            {ADMIN_PHONE}
          </a>
        </p>
      </div>

      <form className="auth-form" onSubmit={handleSubmit}>
        {sent && <p className="form-success">Opening your email client…</p>}
        <label>
          Name
          <input name="name" value={form.name} onChange={handleChange} required />
        </label>
        <label>
          Email
          <input name="email" type="email" value={form.email} onChange={handleChange} required />
        </label>
        <label>
          Message
          <textarea name="message" rows={4} value={form.message} onChange={handleChange} required />
        </label>
        <button type="submit">Send message</button>
      </form>
    </section>
  );
}
